                    for dr, dc in DIRS:
                        check(deadline)
                        start = ((r-k*dr) % n, (c-k*dc) % n, dr, dc)
                        if start in seen:
                            continue
                        seen.add(start)
                        entry = rank(word, start)
                        if entry is not None:
                            ranked.append(entry)
            ranked.sort(reverse=True)
            for _, _, _, start in ranked[:CONFIG["TOP_CANDIDATES"]]:
                check(deadline)
                if place(word, *start):
                    break
            else:
                seen.clear()
                sampled = []
                for _ in range(CONFIG["RANDOM_TRIES"]):
