        global build_attempts
        build_attempts += 1
        grid = []
        pos = {}
        for _ in range(n):
            check(deadline)
            grid.append(["."] * n)

        # A bit represents one grid cell. Union counts shared neighbours once.
        occupied = 0
        neighbours = []
        for r in range(n):
            check(deadline)
            masks = []
            for c in range(n):
                check(deadline)
                mask = 0
                for dr, dc in DIRS:
                    check(deadline)
                    mask |= 1 << (((r + dr) % n) * n + (c + dc) % n)
                masks.append(mask)
            neighbours.append(masks)

        def rank(word, start):
            r, c, dr, dc = start
            overlap = 0
            adjacent = 0
            for letter in word:
                check(deadline)
                cell = grid[r][c]
                if cell == letter:
                    overlap += 1
                elif cell == ".":
                    adjacent |= neighbours[r][c]
                else:
                    return None
                r, c = (r + dr) % n, (c + dc) % n
            if overlap == len(word):
                return None
            touching = (occupied & adjacent).bit_count()
            return placement_rule(overlap), touching, rng.random(), start

        def place(word, r, c, dr, dc):
            nonlocal occupied
            written = []
            for letter in word:
                check(deadline)
                if grid[r][c] == ".":
                    grid[r][c] = letter
                    written.append((r, c))
                r, c = (r + dr) % n, (c + dc) % n
            if has_forbidden(grid, deadline):
                for r, c in written:
                    check(deadline)
                    grid[r][c] = "."
                return False
            for r, c in written:
                check(deadline)
                occupied |= 1 << (r * n + c)
                pos.setdefault(grid[r][c], []).append((r, c))
            return True

        for word in order:
            check(deadline)
            lines = big_string(grid, 2, deadline)
            if word in lines or word[::-1] in lines:
                continue
            ranked = []
            seen = set()
            for k, letter in enumerate(word):
                check(deadline)
                for r, c in pos.get(letter, ()):
                    check(deadline)
                    for dr, dc in DIRS:
                        check(deadline)
                        start = ((r-k*dr) % n, (c-k*dc) % n, dr, dc)
                        if start in seen:
                            continue
                        seen.add(start)
                        entry = rank(word, start)
                        if entry is not None:
                            ranked.append(entry)
            ranked.sort(reverse=True)
            for _, _, _, start in ranked[:CONFIG["TOP_CANDIDATES"]]:
                check(deadline)
                if place(word, *start):
                    break
            else:
                seen.clear()
                sampled = []
                for _ in range(CONFIG["RANDOM_TRIES"]):
                    check(deadline)
                    start = (rng.randrange(n), rng.randrange(n), *rng.choice(DIRS))
                    if start in seen:
                        continue
                    seen.add(start)
                    entry = rank(word, start)
                    if entry is not None:
                        sampled.append(entry)
                        if not occupied:
                            # All starts tie on an empty torus.
                            break
                sampled.sort(reverse=True)
                for _, _, _, start in sampled:
                    check(deadline)
                    if place(word, *start):
                        break
                else:
                    return None

        for row in grid:
            check(deadline)
            for c, cell in enumerate(row):
                check(deadline)
                if cell != ".":
                    continue
                if filler:
                    row[c] = filler
                    continue
                for letter in rng.sample(ALPHABET, 26):
                    check(deadline)
                    row[c] = letter
                    if not has_forbidden(grid, deadline):
                        break
                else:
                    return None
        return verify(grid, deadline)

    target = longest
    while 17 * target * target < 10 * total:
        check(end)
        target += 1
    n = target
    while total / (n * n) > CONFIG["START_DENSITY"]:
        check(end)
        n += 1

    best = None
    try:
        while best is None:
            check(end - CONFIG["FALLBACK_RESERVE"])
            best = try_build(required, int, n, end - CONFIG["FALLBACK_RESERVE"])
